tools.example:
fs = 48000;
b = fir1(128, 4000/(fs/2));
firFilt = dsp.FIRFilter('Numerator', b, 'Structure', 'Direct form symmetric');
scope = spectrumAnalyzer('SampleRate', fs);
for k = 1:200
    x = randn(1024, 1);
    y = firFilt(x);
    scope(y);
end
release(firFilt); release(scope);

fs = 8000;
[b, a] = butter(4, 1000/(fs/2));
iir = dsp.IIRFilter('Numerator', b, 'Denominator', a);
sig = dsp.SineWave('Frequency', 500, 'SampleRate', fs, 'SamplesPerFrame', 512);
for k = 1:50
    y = iir(sig());
end
release(iir);

fs = 44100;
[z, p, k] = ellip(10, 0.5, 80, 5000/(fs/2));
[sos, g] = zp2sos(z, p, k);
biquad = dsp.BiquadFilter('SOSMatrix', sos, ...
    'ScaleValues', [ones(size(sos,1),1); g]);
fvtool(biquad, 'Fs', fs)
y = biquad(randn(4096, 1));

fs = 96000; M = 4;
b = fir1(96, 1/M);
decim = dsp.FIRDecimator('DecimationFactor', M, 'Numerator', b);
x = randn(4096, 1);
y = decim(x);
fprintf('%d in -> %d out (fs %d -> %d)\n', numel(x), numel(y), fs, fs/M);

L = 3;
b = L * fir1(60, 1/L);       % gain L compensates the upsampling loss
interp = dsp.FIRInterpolator('InterpolationFactor', L, 'Numerator', b);
x = sin(2*pi*(0:511)'/64);
y = interp(x);
fprintf('%d -> %d samples\n', numel(x), numel(y));

src = dsp.SampleRateConverter('InputSampleRate', 44100, ...
    'OutputSampleRate', 48000, 'Bandwidth', 20000, ...
    'StopbandAttenuation', 80);
info(src)
[L, M] = getRateChangeFactors(src);
fprintf('Rate change %d/%d\n', L, M);
frameIn = 147 * 10;
y = src(randn(frameIn, 1));

ft = dsp.FFT('FFTLengthSource', 'Property', 'FFTLength', 2048);
ift = dsp.IFFT('FFTLengthSource', 'Property', 'FFTLength', 2048);
x = randn(1024, 1);
X = ft(x);
xr = real(ift(X));
fprintf('Reconstruction error: %.2e\n', max(abs(x - xr(1:1024))));

N = 512;
ft = dsp.FFT('FFTLengthSource', 'Property', 'FFTLength', N);
ift = dsp.IFFT('ConjugateSymmetricInput', true, ...
    'FFTLengthSource', 'Property', 'FFTLength', N);
x = sin(2*pi*(0:N-1)'/32);
X = ft(x);
X(abs(X) < 1) = 0;            % spectral gating
xClean = ift(X);
plot(1:N, x, 1:N, xClean)

fs = 44100;
sa = spectrumAnalyzer('SampleRate', fs, 'SpectrumType', 'Power density', ...
    'RBWSource', 'Property', 'RBW', 10, 'SpectralAverages', 20, ...
    'ChannelNames', {'input','filtered'});
b = fir1(100, 5000/(fs/2));
for k = 1:100
    x = randn(2048, 1);
    sa(x, filter(b, 1, x));
end
release(sa);

fs = 10000;
scope = timescope('SampleRate', fs, 'TimeSpan', 0.1, ...
    'YLimits', [-2 2], 'ShowLegend', true, ...
    'ChannelNames', {'input','envelope'});
for k = 0:99
    t = (k*256:(k+1)*256-1)'/fs;
    x = sin(2*pi*200*t) .* (1 + 0.5*sin(2*pi*5*t));
    scope(x, abs(hilbert(x)));
end
release(scope);

fs = 8000; N = 512;
ap = dsp.ArrayPlot('XOffset', 0, 'SampleIncrement', fs/N, ...
    'YLimits', [-80 20], 'XLabel', 'Frequency (Hz)', ...
    'YLabel', 'Magnitude (dB)', 'Title', 'Live spectrum');
for k = 1:200
    x = randn(N, 1) + sin(2*pi*1000*(0:N-1)'/fs);
    ap(20*log10(abs(fft(x.*hann(N)))));
end
release(ap);

rng(0)
unknown = fir1(31, 0.4)';
x = randn(8000, 1);
d = filter(unknown, 1, x) + 0.01*randn(8000, 1);
lms = dsp.LMSFilter('Length', 32, 'Method', 'Normalized LMS', ...
    'StepSize', 0.1, 'WeightsOutputPort', true);
[y, err, w] = lms(x, d);
plot(unknown, 'o-'); hold on; plot(w, 'x--')
legend('true','identified')
fprintf('Final MSE: %.2e\n', mean(err(end-999:end).^2));

vfd = dsp.VariableFractionalDelay('InterpolationMethod', 'Farrow', ...
    'MaximumDelay', 100, 'FilterHalfLength', 4);
fs = 8000;
t = (0:4095)'/fs;
x = sin(2*pi*300*t);
delays = 10 + 5*sin(2*pi*2*t);   % vibrato-style modulated delay
y = vfd(x, delays);
plot(t(1:500), x(1:500), t(1:500), y(1:500))

dly = dsp.Delay('Length', 5, 'InitialConditions', 0);
out = [];
for k = 1:4
    frame = (1:8)' + (k-1)*8;
    out = [out; dly(frame)];
end
disp(out')     % 0 0 0 0 0 1 2 3 ... correctly delayed across frames

mavg = dsp.MovingAverage(50);
ema = dsp.MovingAverage('Method', 'Exponential weighting', ...
    'ForgettingFactor', 0.98);
scope = timescope('SampleRate', 1000, 'TimeSpan', 2, 'ShowLegend', true);
for k = 1:200
    x = randn(100, 1) + 2;
    scope(x, mavg(x), ema(x));
end
release(scope);

fs = 48000;
d = fdesign.lowpass('Fp,Fst,Ap,Ast', 6000, 8000, 0.5, 80, fs);
designmethods(d)
Hfir = design(d, 'equiripple', 'SystemObject', true);
Hiir = design(d, 'ellip', 'SystemObject', true);
fvtool(Hfir, Hiir, 'Fs', fs)
fprintf('FIR order %d\n', numel(Hfir.Numerator)-1);

reader = dsp.AudioFileReader('guitartune.wav', 'SamplesPerFrame', 1024);
writer = audioDeviceWriter('SampleRate', reader.SampleRate);
while ~isDone(reader)
    frame = reader();
    writer(frame);
end
release(reader); release(writer);

reader = dsp.AudioFileReader('guitartune.wav');
writer = dsp.AudioFileWriter('filtered.wav', ...
    'SampleRate', reader.SampleRate, 'DataType', 'int16');
b = fir1(200, 2000/(reader.SampleRate/2), 'high');
firFilt = dsp.FIRFilter('Numerator', b);
while ~isDone(reader)
    writer(firFilt(reader()));
end
release(reader); release(writer); release(firFilt);

reader = audioDeviceReader('SampleRate', 44100, 'SamplesPerFrame', 512);
sa = spectrumAnalyzer('SampleRate', 44100);
tic
while toc < 10
    [x, overrun] = reader();
    if overrun > 0, fprintf('Dropped %d samples\n', overrun); end
    sa(x);
end
release(reader); release(sa);

fs = 48000;
reader = audioDeviceReader('SampleRate', fs, 'SamplesPerFrame', 256);
writer = audioDeviceWriter('SampleRate', fs);
b = fir1(128, [300 3400]/(fs/2));
filt = dsp.FIRFilter('Numerator', b);
tic
while toc < 15
    underrun = writer(filt(reader()));
end
release(reader); release(writer); release(filt);

fs = 48000;
aPR = audioPlayerRecorder('SampleRate', fs);
sweep = chirp((0:fs-1)'/fs, 20, 1, 20000);
rec = zeros(fs, 1);
N = fs/1024;
for k = 1:N
    idx = (k-1)*1024 + (1:1024);
    [rec(idx), nU, nO] = aPR(sweep(idx));
end
release(aPR);
ir = ifft(fft(rec) ./ fft(sweep));

ads = audioDatastore('speech_commands', 'IncludeSubfolders', true, ...
    'LabelSource', 'foldernames');
disp(countEachLabel(ads))
[adsTrain, adsVal] = splitEachLabel(ads, 0.8, 'randomized');
[x, info] = read(adsTrain);
fprintf('%s: %d samples at %d Hz\n', string(info.Label), numel(x), info.SampleRate);

[audioIn, fs] = audioread('Counting-16-44p1-mono-15secs.wav');
aFE = audioFeatureExtractor('SampleRate', fs, ...
    'Window', hann(round(0.03*fs), 'periodic'), ...
    'OverlapLength', round(0.02*fs), ...
    'mfcc', true, 'mfccDelta', true, ...
    'spectralCentroid', true, 'pitch', true);
features = extract(aFE, audioIn);
idx = info(aFE);
fprintf('%d frames x %d features\n', size(features));
disp(idx)

[x, fs] = audioread('Counting-16-44p1-mono-15secs.wav');
[coeffs, delta, deltaDelta, loc] = mfcc(x, fs, ...
    'NumCoeffs', 13, 'LogEnergy', 'replace');
features = [coeffs delta deltaDelta];
imagesc(loc, 1:size(coeffs,2), coeffs'); axis xy
xlabel('Time (s)'); ylabel('Coefficient')

[x, fs] = audioread('Counting-16-44p1-mono-15secs.wav');
[S, F, T] = melSpectrogram(x, fs, 'NumBands', 64, ...
    'FrequencyRange', [50 8000], 'OverlapLength', round(0.02*fs));
imagesc(T, F, 10*log10(S + eps)); axis xy
xlabel('Time (s)'); ylabel('Frequency (Hz)'); colorbar

[x, fs] = audioread('Counting-16-44p1-mono-15secs.wav');
[f0, loc] = pitch(x, fs, 'Method', 'SRH', 'Range', [60 300], ...
    'MedianFilterLength', 5);
plot(loc/fs, f0)
xlabel('Time (s)'); ylabel('F0 (Hz)')

[x, fs] = audioread('Counting-16-44p1-mono-15secs.wav');
VAD = voiceActivityDetector('SilenceToSpeechProbability', 0.1);
frameLen = 256;
nFrames = floor(numel(x)/frameLen);
p = zeros(nFrames, 1);
for k = 1:nFrames
    p(k) = VAD(x((k-1)*frameLen + (1:frameLen)));
end
plot((0:nFrames-1)*frameLen/fs, p)
ylabel('P(speech)'); xlabel('Time (s)')
